final class PlaceOrderService(orders: OrderRepository, customers: CustomerRepository, ds: DataSource) {
  def place(cmd: PlaceOrderCommand): OrderId = {
    val conn = ds.getConnection
    conn.setAutoCommit(false)                     // explicit demarcation
    try {
      val customer = customers.ofId(conn, cmd.customerId)
      val order = customer.placeOrder(cmd.items)  // the aggregate decides
      orders.add(conn, order)
      conn.commit()
      order.id
    } catch { case e: Throwable => conn.rollback(); throw e } finally conn.close()
  }
}
